"""Second generator: meaningful clusters, kept patterns and segment matches.

Discovery rows place a clearly separated high-activation run over a template,
validation rows reuse templates so coverage is non-trivial, and blocks can
spell exact packet sequences that the online tables should recognise.
"""
import random

PAD = 1514


def band_value(rng, band):
    if band == 0:
        return rng.randint(1600, 1700)
    if band == 1:
        return rng.randint(1400, 1500)
    return rng.choice([rng.randint(1300, 1500), rng.randint(1520, 1750)])


def make_release(rng, index, templates_by_class, style):
    classes = rng.randint(1, 4)
    width = rng.randint(2, 6)
    mode = rng.choice(['range', 'exact'])
    discovery = []
    for cls in range(classes):
        pool = templates_by_class[cls]
        for _ in range(rng.randint(1, 6)):
            base = pool[rng.randrange(len(pool))]
            values = list(base)
            if style and rng.random() < 0.5:
                values = [v + rng.choice([-2, -1, 0, 0, 1, 2]) for v in values]
                values = [PAD + 1 if v == PAD else v for v in values]
            lead = rng.randint(0, 3)
            tail = rng.randint(0, 3)
            head_values = [rng.randint(1000, 2000) for _ in range(lead)]
            end_values = [rng.randint(1000, 2000) for _ in range(tail)]
            for position in range(len(head_values)):
                if head_values[position] == PAD:
                    head_values[position] += 1
            for position in range(len(end_values)):
                if end_values[position] == PAD:
                    end_values[position] += 1
            row_values = head_values + values + end_values
            high = 1000
            activations = [rng.randint(0, 20) for _ in row_values]
            for position in range(lead, lead + len(values)):
                if rng.random() < 0.75:
                    activations[position] = high
            if rng.random() < 0.4:
                row_values = row_values + [PAD] * rng.randint(1, 3)
                activations = activations + [rng.randint(0, 30) for _ in range(
                    len(row_values) - len(activations))]
            if len(row_values) < 2:
                row_values = row_values + [1600, 1601]
                activations = activations + [high, 5]
            discovery.append({'class': cls, 'values': row_values,
                              'activation': activations})
    rng.shuffle(discovery)

    def rows_for(group):
        out = []
        for cls in range(classes):
            pool = templates_by_class[cls]
            for _ in range(rng.randint(1, 5)):
                base = pool[rng.randrange(len(pool))]
                values = list(base)
                if group == 'train' and rng.random() < 0.5:
                    values = [v + rng.randint(-3, 3) for v in values]
                    values = [PAD + 1 if v == PAD else v for v in values]
                if rng.random() < 0.4:
                    values = values + [PAD] * rng.randint(1, 2)
                out.append({'class': cls, 'values': values})
        rng.shuffle(out)
        return out

    train = rows_for('train')
    validation = rows_for('validation')
    eps = rng.choice([[1, 1], [0, 1], [10, 1], [1, 2], [50, 100], [2, 1], [200, 100],
                      [4, 1], [30, 10]])
    ratio = rng.choice([[0, 1], [1, 4], [1, 2], [1, 3], [2, 3]])
    threshold = rng.choice([[0, 1], [1, 1], [10, 1], [100, 1], [1000, 1], [1, 1],
                            [9999, 1], [10000, 1], [2, 1]])
    templates = [t for pool in templates_by_class.values() for t in pool]
    return {'id': 'r%d' % index, 'classes': classes, 'width': width, 'eps': eps,
            'ratio': ratio, 'threshold': threshold, 'mode': mode,
            'packet_limit': rng.choice([width, width + 1, width + 2, max(width, 5),
                                       max(width, 9)]),
            'idle_us': rng.choice([0, 1, 5, 40, 10 ** 9]),
            'discovery': discovery, 'train': train, 'validation': validation}, templates


def make_templates(rng, classes):
    out = {}
    for cls in range(classes):
        pool = []
        for _ in range(rng.randint(1, 3)):
            length = rng.randint(2, 7)
            band = rng.randint(0, 2)
            pool.append([band_value(rng, band) for _ in range(length)])
        out[cls] = pool
    return out


def simulate_install(state, mid, info, capacity):
    mode, entries = info[mid]
    pool = 'range' if mode == 'range' else 'exact'
    current = state['current']
    evict = None
    if current is not None and current != mid and state['refs'].get(current, 0) == 0:
        evict = current
    prospective = set(state['resident'])
    if evict is not None:
        prospective.discard(evict)
    prospective.add(mid)
    status = 'ok'
    if entries > capacity[pool]:
        status = 'oversize'
    else:
        used_r = sum(info[x][1] for x in prospective if info[x][0] == 'range')
        used_e = sum(info[x][1] for x in prospective if info[x][0] == 'exact')
        if used_r > capacity['range'] or used_e > capacity['exact']:
            status = 'busy'
    if status == 'ok':
        if evict is not None:
            state['resident'].discard(evict)
        state['resident'].add(mid)
        state['current'] = mid
    return status


def feature_packet(positive, value):
    """(src, length) producing one encoded feature value in an epoch."""
    if value == PAD:
        value = PAD + 1
    if value > PAD:
        return (positive if positive is not None else 0, value - PAD)
    return (1 - (positive or 0), PAD - value)


def make_blocks(rng, releases, info, capacity, spells):
    state = {'current': None, 'resident': set(), 'refs': {}}
    ops = []
    active = {}
    count = rng.randint(25, 140)
    for _ in range(count):
        roll = rng.random()
        if roll < 0.14 or state['current'] is None:
            mid = rng.choice(releases)
            simulate_install(state, mid, info, capacity)
            ops.append(['install', mid])
            continue
        if roll < 0.24:
            flow = 'f%d' % rng.randint(0, 4)
            if flow in active:
                continue
            mid = state['current']
            simulate_install(state, mid, info, capacity)
            state['refs'][mid] = state['refs'].get(mid, 0) + 1
            active[flow] = {'release': mid, 'positive': None, 'stamp': 0,
                            'spell': rng.choice(spells.get(mid, [[]]) or [[]]),
                            'cursor': 0}
            ops.append(['open', flow])
            continue
        if active and roll < 0.75:
            flow = rng.choice(list(active))
            epoch = active[flow]
            spell = epoch['spell']
            stamp = epoch['stamp']
            if rng.random() < 0.7 and epoch['cursor'] < len(spell):
                value = spell[epoch['cursor']]
                epoch['cursor'] += 1
                src, length = feature_packet(epoch['positive'], value)
                if epoch['positive'] is None:
                    epoch['positive'] = src
                stamp += rng.choice([0, 1, 2])
            else:
                src = rng.randint(0, 1)
                if epoch['positive'] is None:
                    epoch['positive'] = src
                length = rng.choice([1, 40, 100, 500, 1514, rng.randint(1, 1514)])
                stamp += rng.choice([0, 0, 1, 5, 60])
            epoch['stamp'] = stamp
            ops.append(['packet', flow, stamp, src, length])
            continue
        if active:
            flow = rng.choice(list(active))
            ops.append(['close', flow])
            mid = active.pop(flow)['release']
            state['refs'][mid] -= 1
            if state['refs'][mid] == 0 and state['current'] != mid:
                state['resident'].discard(mid)
            continue
        mid = rng.choice(releases)
        simulate_install(state, mid, info, capacity)
        ops.append(['install', mid])
    for flow in list(active):
        ops.append(['close', flow])
        mid = active.pop(flow)['release']
        state['refs'][mid] -= 1
    blocks = []
    while ops:
        size = rng.randint(1, 6)
        blocks.append(ops[:size])
        ops = ops[size:]
    return blocks


def make_request(seed, with_blocks=True):
    rng = random.Random(seed)
    templates = make_templates(rng, 4)
    releases = []
    info = {}
    spells = {}
    specs = []
    all_templates = {}
    for index in range(rng.randint(1, 3)):
        classes = rng.randint(1, 4)
        by_class = {cls: templates[cls][:max(1, len(templates[cls]) // 2)]
                    for cls in range(4)}
        spec, pool = make_release(rng, index, by_class, rng.random() < 0.6)
        specs.append(spec)
        all_templates[spec['id']] = pool
    capacity = {'range': rng.choice([0, 1, 2, 4, 16, 4096]),
                'exact': rng.choice([0, 1, 4, 32, 4096, 8192])}
    if not with_blocks:
        return {'capacity': capacity, 'releases': specs, 'blocks': []}
    import reference
    for spec in specs:
        model = reference.build_model(spec, capacity)
        info[spec['id']] = (model['mode'], model['entries'])
        spells[spec['id']] = all_templates[spec['id']]
    ids = [spec['id'] for spec in specs]
    return {'capacity': capacity, 'releases': specs,
            'blocks': make_blocks(rng, ids, info, capacity, spells)}
PYEOF
